can_ignore = False
for i in range(n):
    # Check if all lamps can be turned on without switch i
    lamps_covered = set()
    for j in range(n):
        if j == i:
            continue
        # Add lamps covered by this switch
        for k in range(m):
            if switches[j][k] == '1':
                lamps_covered.add(k)

    # Check if all m lamps are covered
    if len(lamps_covered) == m:
        can_ignore = True
        break

print("YES" if can_ignore else "NO")
"}

