def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

q = int(input())
for _ in range(q):
    s = input().strip()
    t = input().strip()
    len_s = len(s)
    len_t = len(t)
    length = lcm(len_s, len_t)

    # Check if s repeated (length/len_s) times equals t repeated (length/len_t) times
    x = length // len_s
    y = length // len_t

    # Build the candidate string
    candidate = s * x

    # Check if candidate equals t repeated y times
    if candidate == t * y:
        print(candidate)
    else:
        print(-1)
"}

