from sys import stdin

def is_valid(sequence):
    """Check if a sequence is a valid bracket sequence"""
    stack = []
    for char in sequence:
        if char == '(' or char == '[':
            stack.append(char)
        else:
            if not stack:
                return False
            top = stack.pop()
            if (char == ')' and top != '(') or (char == ']' and top != '['):
                return False
    return len(stack) == 0

s = stdin.readline().strip()

max_square_brackets = 0
best_sequence = ""

for i in range(len(s)):
    for j in range(i, len(s)):
        seq = s[i:j+1]
        if is_valid(seq):
            count = seq.count('[')
            # Prefer sequences with more '['
            # If tie, prefer lexicographically smaller (or any)
            if count > max_square_brackets or (count == max_square_brackets and seq < best_sequence):
                max_square_brackets = count
                best_sequence = seq

print(max_square_brackets)
print(best_sequence)
"}

