def is_perfect_square(x):
    if x < 0:
        return False
    root = int(x**0.5)
    return root * root == x

MOD = 10**9 + 7

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Count frequency of each number
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # List of unique numbers
    unique_nums = list(freq.keys())
    m = len(unique_nums)

    # DP table: dp[mask][i] = number of ways to build a permutation ending with unique_nums[i]
    # mask represents which unique numbers we've already used
    dp = [[0] * m for _ in range(1 << m)]

    # Initialize with numbers that can be placed first
    for i in range(m):
        dp[1 << i][i] = freq[unique_nums[i]]

    # Build up permutations
    for mask in range(1 << m):
        for i in range(m):
            if (mask & (1 << i)) == 0:
                # i-th unique number hasn't been used yet
                for j in range(m):
                    if mask & (1 << j):
                        # j-th unique number has been used
                        if not is_perfect_square(unique_nums[j] * unique_nums[i]):
                            # Add i-th number to a permutation ending with j-th number
                            dp[mask | (1 << i)][i] = (dp[mask | (1 << i)][i] + dp[mask][j]) % MOD

    # Sum all ways to build a complete permutation
    result = 0
    for i in range(m):
        result = (result + dp[(1 << m) - 1][i]) % MOD

    print(result)

solve()
