import sys

def reflection(n):
    s = str(n)
    res = ""
    for ch in s:
        res += str(9 - int(ch))
    if res[0] == "0":  # remove leading zeros
        res = res[1:] if len(res) > 1 else "0"
    return int(res) if res else 0

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    l, r = int(data[0]), int(data[1])

    max_weight = 0
    for n in range(l, r + 1):
        weight = n * reflection(n)
        if weight > max_weight:
            max_weight = weight

    sys.stdout.write(str(max_weight))

if __name__ == "__main__":
    solve()
"}

