import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    data = list(map(int, data))
    if not data:
        return

    n = data[0]
    stamps = data[1:]

    # Build adjacency list with edge indices
    adj = {}
    for i in range(n):
        a = stamps[2*i]
        b = stamps[2*i+1]
        if a not in adj:
            adj[a] = {}
        if b not in adj:
            adj[b] = {}
        adj[a][b] = i
        adj[b][a] = i

    # Find all cities
    cities = sorted(adj.keys())

    # Try both starting points
    for start_city in cities:
        visited = set()
        path = []

        current = start_city
        path.append(current)
        visited.add(current)

        used_edges = set()

        while len(path) < n + 1:
            neighbors = adj[current]
            next_city = None
            next_edge_idx = None

            for neighbor, edge_idx in neighbors.items():
                if neighbor not in visited:
                    next_city = neighbor
                    next_edge_idx = edge_idx
                    break

            if next_city is None:
                # This should never happen
                break

            path.append(next_city)
            visited.add(next_city)
            used_edges.add(next_edge_idx)
            current = next_city

        if len(path) == n + 1:
            print(' '.join(map(str, path)))
            return

if __name__ == '__main__':
    solve()
