import sys

def read_grid(rows):
    """Read a grid with the given number of rows from stdin"""
    return [sys.stdin.readline().strip() for _ in range(rows)]

def compare_submatrices(grid1, grid2, i, j, M):
    """Compare M×M submatrices: grid1 from row i, grid2 from column j"""
    # Extract submatrix from grid1 (N×M) starting at row i (1-indexed)
    sub1 = ''.join([grid1[i+k][0:M] for k in range(M)])

    # Extract submatrix from grid2 (M×N) starting at column j (1-indexed)
    sub2 = ''.join([grid2[k][j-1:j-1+M] for k in range(M)])

    return sub1 == sub2

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])

    # Read first N lines for the first map (N×M)
    first_map = data[2:2+N]

    # Read next M lines for the second map (M×N)
    second_map = data[2+N:2+N+M]

    # Try all possible starting positions
    for i in range(1, N-M+2):
        for j in range(1, N-M+2):
            if compare_submatrices(first_map, second_map, i, j, M):
                print(f"{i} {j}")
                return

