from collections import deque

def solve():
    n, m, k = map(int, input().split())
    grid = []
    start_pos = None
    end_pos = None

    for i in range(n):
        row = list(input())
        grid.append(row)
        for j in range(m):
            if row[j] == 'S':
                start_pos = (i, j)
            elif row[j] == 'T':
                end_pos = (i, j)

    # BFS: state = (row, col, frozenset(types_used))
    # For each state, track distance and best path string
    dist = {}
    best_path = {}
    q = deque()

    # Start state: at 'S', no types used
    start_state = (start_pos[0], start_pos[1], frozenset())
    dist[start_state] = 0
    best_path[start_state] = ""
    q.append(start_state)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while q:
        r, c, types_used = q.popleft()
        current_dist = dist[(r, c, types_used)]
        current_path = best_path[(r, c, types_used)]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                cell = grid[nr][nc]

                if cell == 'S':
                    continue  # Can't revisit 'S'

                if cell == 'T':
                    # Reached end
                    new_state = (nr, nc, types_used)
                    new_dist = current_dist + 1
                    new_path = current_path

                    if new_state not in dist or new_dist < dist[new_state]:
                        dist[new_state] = new_dist
                        best_path[new_state] = new_path
                        q.append(new_state)
                    elif new_dist == dist[new_state]:
                        # Update if lexicographically smaller
                        if new_path < best_path[new_state]:
                            best_path[new_state] = new_path
                    continue

                # Cell has terrain type
                t = cell
                if t in types_used:
                    # Already used this type
                    new_state = (nr, nc, types_used)
                    new_dist = current_dist + 1
                    new_path = current_path + t

                    if new_state not in dist or new_dist < dist[new_state]:
                        dist[new_state] = new_dist
                        best_path[new_state] = new_path
                        q.append(new_state)
                    elif new_dist == dist[new_state]:
                        if new_path < best_path[new_state]:
                            best_path[new_state] = new_path
                else:
                    if len(types_used) + 1 > k:
                        continue  # Would exceed k different types
                    new_types = types_used | frozenset([t])
                    new_state = (nr, nc, new_types)
                    new_dist = current_dist + 1
                    new_path = current_path + t

                    if new_state not in dist or new_dist < dist[new_state]:
                        dist[new_state] = new_dist
                        best_path[new_state] = new_path
                        q.append(new_state)
                    elif new_dist == dist[new_state]:
                        if new_path < best_path[new_state]:
                            best_path[new_state] = new_path

    # Find the best path to T
    best_T_state = None
    best_T_dist = float('inf')
    best_T_path = ""

    for state, path in best_path.items():
        if state[0] == end_pos[0] and state[1] == end_pos[1]:
            if dist[state] < best_T_dist:
                best_T_dist = dist[state]
                best_T_path = path
            elif dist[state] == best_T_dist:
                if path < best_T_path:
                    best_T_path = path

    if best_T_path:
        print(best_T_path)
    else:
        print(-1)

solve()
