n = int(input())
a = list(map(int, input().split()))

# We need to inform n students, starting with student 1
informed = [False] * n
informed[0] = True  # 0-indexed for student 1
remaining = [a[i] for i in range(n)]

messages = []

# Use a queue for students who know the news and have remaining messages
from collections import deque
queue = deque([0])  # Start with student 1

while queue and sum(informed) < n:
    sender = queue.popleft()

    # Find the student who needs to be informed
    if sum(informed) == n - 1:
        # Only one student left to inform
        for receiver in range(n):
            if not informed[receiver]:
                if remaining[sender] > 0:
                    messages.append((sender + 1, receiver + 1))
                    informed[receiver] = True
                    remaining[sender] -= 1
                    queue.append(receiver)
                break
    else:
        # Find the student with highest remaining capacity to inform
        max_remaining = -1
        best_receiver = -1

        for receiver in range(n):
            if not informed[receiver]:
                if remaining[receiver] > max_remaining:
                    max_remaining = remaining[receiver]
                    best_receiver = receiver

        if best_receiver != -1 and remaining[sender] > 0:
            messages.append((sender + 1, best_receiver + 1))
            informed[best_receiver] = True
            remaining[sender] -= 1
            queue.append(best_receiver)

if sum(informed) == n:
    print(len(messages))
    for f, t in messages:
        print(f, t)
else:
    print(-1)
