    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        k = int(next(it))
        z = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # DP: dp[l][i][last] = max score
        # l: number of left moves made
        # i: current position (1-indexed)
        # last: 0 = last move was right, 1 = last move was left
        dp = [[[-1 for _ in range(2)] for _ in range(n + 1)] for _ in range(z + 1)]

        # Base case: start at position 1, score = a[0], last move is right
        dp[0][1][0] = a[0]

        # Fill DP table
        for l in range(z + 1):
            for i in range(1, n + 1):
                # Move right from i to i+1
                if i < n and dp[l][i][0] != -1:
                    if dp[l][i+1][1] == -1 or dp[l][i+1][1] < dp[l][i][0] + a[i]:
                        dp[l][i+1][1] = dp[l][i][0] + a[i]

                # Move left from i to i-1 (only if last move was right and we haven't exceeded left moves)
                if l < z and i > 1 and dp[l][i][0] != -1:
                    if dp[l+1][i-1][1] == -1 or dp[l+1][i-1][1] < dp[l][i][0] + a[i-1]:
                        dp[l+1][i-1][1] = dp[l][i][0] + a[i-1]

        # Find the maximum score after exactly k moves
        max_score = -1
        for l in range(z + 1):
            for i in range(1, n + 1):
                if dp[l][i][0] != -1 and l + (i - 1) == k:
                    max_score = max(max_score, dp[l][i][0])
                if dp[l][i][1] != -1 and l + (i - 1) == k:
                    max_score = max(max_score, dp[l][i][1])

        out_lines.append(str(max_score))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
