import sys

def solve():
    # Read input
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    n = int(data[0])
    m = int(data[1])

    # Read x array
    x = list(map(int, data[2:2+n]))

    # Read y array
    y = list(map(int, data[2+n:2+n+m]))

    # Compute prefix sums
    prefix_sums_x = [0]
    for val in x:
        prefix_sums_x.append(prefix_sums_x[-1] + val)

    prefix_sums_y = [0]
    for val in y:
        prefix_sums_y.append(prefix_sums_y[-1] + val)

    # DP: dp[i][j] = max number of files with prefix i of x and prefix j of y
    # Initialize with all -1
    dp = [[-1] * (len(prefix_sums_y)) for _ in range(len(prefix_sums_x))]

    # Base case: empty prefix
    dp[0][0] = 0

    # Fill DP table
    for i in range(1, len(prefix_sums_x)):
        for j in range(1, len(prefix_sums_y)):
            if prefix_sums_x[i] == prefix_sums_y[j]:
                dp[i][j] = max(dp[i-1][j-1] + 1, dp[i-1][j], dp[i][j-1])
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # Find the maximum number of files
    max_files = 0
    for i in range(1, len(prefix_sums_x)):
        for j in range(1, len(prefix_sums_y)):
            if dp[i][j] > max_files:
                max_files = dp[i][j]

    print(max_files)

if __name__ == '__main__':
    solve()
