def parse_time(time_str):
    # time_str is in format "hh:mm x.m."
    time_part, period = time_str.split(']')[0][1:], time_str.split(']')[1]
    hh, mm = map(int, time_part.split(':'))
    if period == 'a.m.':
        if hh == 12:
            hh = 0  # 12 a.m. is midnight
    else:  # p.m.
        if hh != 12:
            hh += 12
    return hh * 60 + mm

