# For each position, we can choose which type to get (or get nothing)
# We'll use backtracking to try all combinations

def backtrack(pos_idx, current_types, total_moves):
    global min_moves

    if pos_idx == n:
        # Check if we have all three types
        if current_types == {'digit', 'letter', 'special'}:
            min_moves = min(min_moves, total_moves)
        return

    # Try not using this position (get nothing)
    backtrack(pos_idx + 1, current_types, total_moves)

    # Try using this position for each possible type it can contribute
    for moves, char_type in positions[pos_idx].items():
        if char_type not in current_types:
            backtrack(pos_idx + 1, current_types | {char_type}, total_moves + moves)

