# Read nodes: (color, sum)
nodes = []
for _ in range(n):
    ci, si = map(int, input().split())
    nodes.append((ci, si))

# Split into white (0) and black (1)
white_nodes = []  # (index, sum)
black_nodes = []  # (index, sum)
for i in range(n):
    if nodes[i][0] == 0:
        white_nodes.append((i, nodes[i][1]))
    else:
        black_nodes.append((i, nodes[i][1]))

# If all nodes are the same color, it's a tree with no edges
if not white_nodes or not black_nodes:
    exit()

# Find a black node to connect all white nodes to (prefer one with sum 0)
black_zero = None
for i in range(len(black_nodes)):
    idx, s = black_nodes[i]
    if s == 0:
        black_zero = (idx, s)
        break

if black_zero is None:
    # Connect to first black node
    idx, s = black_nodes[0]
    black_zero = (idx, s)

# Connect all white nodes to black_zero with weight 0
edges = []
for s_idx, s_sum in white_nodes:
    edges.append((s_idx + 1, black_zero[0] + 1, 0))

# Now connect remaining white nodes to other black nodes
for i in range(len(white_nodes)):
    s_idx, s_sum = white_nodes[i]
    while s_sum > 0:
        # Find a black node with sum > 0 (not the one we already connected)
        for j in range(len(black_nodes)):
            t_idx, t_sum = black_nodes[j]
            if t_sum > 0 and t_idx != black_zero[0]:
                give = min(s_sum, t_sum)

                edges.append((s_idx + 1, t_idx + 1, give))

                s_sum -= give
                t_sum -= give

                break

# Output edges
for edge in edges:
    print(edge[0], edge[1], edge[2])
