import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    q = [int(next(it)) for _ in range(n)]
    m = int(next(it))
    edges = [[] for _ in range(n + 1)]  # 1-indexed

    for _ in range(m):
        ai = int(next(it))
        bi = int(next(it))
        ci = int(next(it))
        edges[ai].append((bi, ci))

    # Find the node(s) with maximum qualification
    max_qual = max(q)
    root_candidates = [i + 1 for i in range(n) if q[i] == max_qual]

    # If there are no nodes with max qualification, it's impossible (all zero? but n >= 1)
    if not root_candidates:
        print(-1)
        return

    # Try each root candidate
    min_total = float('inf')
    for root in root_candidates:
        cost = 0
        assigned = {root}

        while len(assigned) < n:
            # Find the node with the smallest minimum incoming edge cost
            min_cost = float('inf')
            min_node = -1

            for node in range(1, n + 1):
                if node not in assigned:
                    # Find the minimum cost edge where this node is the subordinate
                    # and the supervisor has higher qualification
                    for ai in range(1, n + 1):
