import math

def solve():
    n, k = map(int, input().split())

    # Special case: k == 0 is impossible
    if k == 0:
        print(-1)
        return

    # If n is even, we need to get exactly k by pairing numbers
    # If n is odd, we need to get exactly k by pairing (n-1)/2 numbers
    result = []
    seen = set()

    # Try to construct a sequence that gives the desired sum
    # Start with some specific values
    if n % 2 == 0:
        # For even n, try specific pairs
        pairs = []
        if k >= 1:
            pairs.append((1, 2))  # gcd = 1
        if k >= 2:
            pairs.append((4, 8))  # gcd = 4
        if k >= 3:
            pairs.append((6, 9))  # gcd = 3

        # Fill in remaining pairs with ones that contribute 1
        while len(pairs) < n // 2:
            if k >= 1:
                pairs.append((10, 10))  # gcd = 10 (should be distinct!)

        # Now construct the sequence
        for i in range(len(pairs)):
            a, b = pairs[i]
            result.append(a)
            result.append(b)
    else:
        # For odd n, try specific pairs and leave one number at the end
        pairs = []
        if k >= 1:
            pairs.append((1, 2))  # gcd = 1
        if k >= 2:
            pairs.append((4, 8))  # gcd = 4
        if k >= 3:
            pairs.append((6, 9))  # gcd = 3

        # Fill in remaining pairs with ones that contribute 1
        while len(pairs) < (n-1) // 2:
            if k >= 1:
                pairs.append((10, 10))  # gcd = 10

        # Add the last number (should be distinct from all others)
        result.extend([100])

    # Check if we have exactly n numbers
    if len(result) != n:
        print(-1)
        return

    # Check if all numbers are distinct
    if len(set(result)) != n:
        print(-1)
        return

    # Calculate the total points
    total = 0
    i = 0
    while i < len(result) - 1:
        total += math.gcd(result[i], result[i + 1])
        i += 2

    if total == k:
        print(' '.join(map(str, result)))
    else:
        print(-1)

solve()
