def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    status = data[1] if len(data) > 1 else ''

    # Count non-FOLDED cows and their types
    non_folded = 0
    has_IN = False

    for c in status:
        if c == 'A':
            non_folded += 1
        elif c == 'I':
            non_folded += 1
