    for i in range(n):
        for j in range(i + 1, n):
            if remaining > 0:
                matrix[i][j] = 1
                matrix[j][i] = 1
                remaining -= 2

    # Print matrix
    for row in matrix:
        print(' '.join(map(str, row)))
