import sys

def parse_time(time_str):
    """Parse a 12-hour time string into minutes since midnight"""
    # Extract hour, minute, and AM/PM
    time_part = time_str.split(':')[0].strip()
    time, period = time_part.split(' ')
    hour_str, minute_str = time.split(':')
    hour = int(hour_str)
    minute = int(minute_str)

    # Convert to 24-hour format
    if period == 'a.m.':
        if hour == 12:
            hour = 0
    else:  # p.m.
        if hour != 12:
            hour += 12

    return hour * 60 + minute

n = int(sys.stdin.readline())
entries = []

for _ in range(n):
    line = sys.stdin.readline().strip()
    entries.append(line)

# Parse all times
times = []
for entry in entries:
    time_str = entry.split(':')[0].strip()[1:]  # Remove the opening [
    times.append(parse_time(time_str))

# Now process the log
min_days = 1

current_day_entries = {}  # key: minute of day, value: count

current_day_time = times[0]

current_day_entries[current_day_time] = 1

for i in range(1, n):
    current_time = times[i]

    # If time is earlier, start a new day
    if current_time < current_day_time:
        min_days += 1
        current_day_time = current_time
        current_day_entries = {current_time: 1}

    # If time is later, check if we can fit in current day
    elif current_time > current_day_time:
        # Check if same minute and count < 10
        if current_time in current_day_entries:
            if current_day_entries[current_time] < 10:
                current_day_entries[current_time] += 1
            else:
                # Can't fit, start new day
                min_days += 1
                current_day_time = current_time
                current_day_entries = {current_time: 1}
        else:
            # Different minute, just add
            current_day_entries[current_time] = 1

    # If time is same, check if we can fit
    elif current_time == current_day_time:
        if current_day_entries[current_time] < 10:
            current_day_entries[current_time] += 1
        else:
            # Can't fit, start new day
            min_days += 1
            current_day_time = current_time
            current_day_entries = {current_time: 1}

print(min_days)
