h, w = map(int, input().split())
grid = [input().strip() for _ in range(h)]

# Find potential center candidates (cells with non-empty cells in all four directions)
centers = []
for i in range(h):
    for j in range(w):
        if grid[i][j] == '*':
            has_left = False
            for k in range(j-1, -1, -1):
                if grid[i][k] == '*':
                    has_left = True
                else:
                    break

            has_right = False
            for k in range(j+1, w):
                if grid[i][k] == '*':
                    has_right = True
                else:
                    break

            has_up = False
            for k in range(i-1, -1, -1):
                if grid[k][j] == '*':
                    has_up = True
                else:
                    break

            has_down = False
            for k in range(i+1, h):
                if grid[k][j] == '*':
                    has_down = True
                else:
                    break

            if has_left and has_right and has_up and has_down:
                centers.append((i, j))

# There must be exactly one center
if len(centers) != 1:
    print("NO")
else:
    center = centers[0]

    # Check that all non-empty cells form rays from this center
    all_non_empty = set()
    for i in range(h):
        for j in range(w):
            if grid[i][j] == '*':
                all_non_empty.add((i, j))

    valid = True
    for (i, j) in all_non_empty:
        if i == center[0] and j == center[1]:
            continue  # skip the center

        # Check if this cell is on a ray from the center
        if i == center[0]:  # same row (horizontal ray)
            if abs(j - center[1]) > 1:  # not adjacent
                valid = False
                break
        elif j == center[1]:  # same column (vertical ray)
            if abs(i - center[0]) > 1:  # not adjacent
                valid = False
                break
        else:
            valid = False

    if valid:
        print("YES")
    else:
        print("NO")
