grid = [input().strip() for _ in range(h)]

# Find potential center candidates (cells with non-empty cells in all four directions)
centers = []
for i in range(h):
    for j in range(w):
        if grid[i][j] == '*':
            has_left = False
            for k in range(j-1, -1, -1):
                if grid[i][k] == '*':
                    has_left = True
                else:
                    break

            has_right = False
            for k in range(j+1, w):
                if grid[i][k] == '*':
                    has_right = True
                else:
                    break

            has_up = False
            for k in range(i-1, -1, -1):
                if grid[k][j] == '*':
                    has_up = True
                else:
                    break

            has_down = False
            for k in range(i+1, h):
                if grid[k][j] == '*':
                    has_down = True
                else:
                    break

            if has_left and has_right and has_up and has_down:
                centers.append((i, j))

# There must be exactly one center
if len(centers) != 1:
    print("NO")
else:
    center = centers[0]

    # Check that all non-empty cells form a single continuous path from this center
    all_non_empty = set()
    for i in range(h):
        for j in range(w):
            if grid[i][j] == '*':
                all_non_empty.add((i, j))

    # Start from the center and trace the rays
    visited = set()
    visited.add(center)
    to_visit = [center]

    # Trace left ray
    i, j = center
    while j > 0 and grid[i][j-1] == '*':
        j -= 1
        visited.add((i, j))
        to_visit.append((i, j))

    # Trace right ray
    i, j = center
    while j < w-1 and grid[i][j+1] == '*':
        j += 1
        visited.add((i, j))
        to_visit.append((i, j))

