# Use a stack to find valid bracket sequences
stack = []
valid_start_indices = []
valid_end_indices = []
valid_count = []

current_start = -1
for i, char in enumerate(s):
    if char in ('(', '['):
        # Opening bracket
        stack.append((char, i))
    elif char == ')':
        if stack and stack[-1][0] == '(': 
            stack.pop()
            if current_start == -1:
                current_start = stack[-1][1] + 1 if stack else i + 1
        else:
            # Invalid, reset
            current_start = -1
    elif char == ']':
        if stack and stack[-1][0] == '[':
            stack.pop()
            if current_start == -1:
                current_start = stack[-1][1] + 1 if stack else i + 1
        else:
            # Invalid, reset
            current_start = -1

    # If we're in a valid sequence, record end index
    if current_start != -1:
        valid_end_indices.append(i)
        valid_count.append(i - current_start + 1)

# Now find the maximum
if valid_start_indices:
    max_count = max(valid_count)
    # Find all subsequences with this count
    for i, count in enumerate(valid_count):
        if count == max_count:
            # Find the corresponding sequence
            start = valid_start_indices[i]
            end = valid_end_indices[i]
            print(max_count)
            print(s[start:end+1])
            break
else:
    print(0)
    print()
