    # Check candidates: optimal, start, end, and the nearest boundary
    candidates = [start, end]
    if start <= optimal <= end:
        candidates.append(optimal)
        # Check the closest boundaries if optimal is near the edge
        if optimal - start < end - optimal:
            candidates.append(start + 1)
        if optimal - start > end - optimal:
            candidates.append(end - 1)
    else:
        # If optimal is outside the range, check which boundary is better
        if reflection(start) > reflection(end):
            candidates.append(start)
        else:
            candidates.append(end)

    # Add the optimal even if it's outside the range
    if optimal <= end:
        candidates.append(optimal)
    elif optimal >= start:
        candidates.append(optimal)
    else:
        if reflection(start) > reflection(end):
            candidates.append(start)
        else:
            candidates.append(end)

    for n in set(candidates):
        if start <= n <= end and l <= n <= r:
            weight = n * reflection(n)
            if weight > max_weight:
                max_weight = weight

    k += 1

