# Function to compute reflection
def reflection(n):
    return int(''.join(str(9 - int(d)) for d in str(n)))

# Compute weight
def weight(n):
    return n * reflection(n)

# Find maximum weight in range [l, r]
max_weight = 0

# Check endpoints
max_weight = max(max_weight, weight(l), weight(r))

# Check middle values for each digit length
for digits in range(1, len(str(r)) + 1):
    # The middle value for this digit length
    mid = (10**digits - 1) // 2  # This is the middle of the range [10^{digits-1}, 10^digits - 1]
    if l <= mid <= r:
        max_weight = max(max_weight, weight(mid))

print(max_weight)
