def number_of_digits(n):
    return len(str(n))

def main():
    w, m, k = map(int, input().split())

    current = m
    remaining = w
    length = 0

    while True:
        cost = number_of_digits(current) * k

        if cost <= remaining:
            remaining -= cost
            length += 1
            current += 1
        else:
            break

    print(length)

if __name__ == "__main__":
    main()
"}

