def count_pythagorean_triples(n):
    # For each test case
    result = []

    # Try odd values of a
    a = 3
    while True:
        b = (a * a - 1) // 2
        c = (a * a + 1) // 2

        # Check if c is within bounds
        if c > n:
            break

        # Check if a ≤ b ≤ c
        if a <= b and b <= c:
            result.append(1)
        else:
            result.append(0)

        a += 2

    # Print all results
    for r in result:
        print(r)

