{"code": "
n, k = map(int, input().split())

# Matrix to fill with 0s
matrix = [[0 for _ in range(n)] for _ in range(n)]

# Try to place ones greedily in lexicographical order
for i in range(n):
    for j in range(n):
        # Only consider positions (i, j) where i <= j (above or on diagonal)
        if i > j:
            continue

        # Calculate cost of placing a 1 at (i, j)
        if i == j:
            cost = 1
        else:
            cost = 2

        # If we can place a 1 and we still have k left
        if k >= cost:
            # Place 1 at (i, j) and (j, i) if not on diagonal
            matrix[i][j] = 1
            if i != j:
                matrix[j][i] = 1
            k -= cost

            # After placing a 1, we're done for this row
            break

# Check if we used exactly k ones
if k != 0:
    print(-1)
else:
    for row in matrix:
        print(' '.join(map(str, row)))
"}

