def is_perfect_square(x):
    s = int(x**0.5)
    return s * s == x

def count_right_permutations(n, a):
    from collections import defaultdict
    from math import gcd
    from itertools import permutations

    # Group by value
    value_count = defaultdict(int)
    for num in a:
        value_count[num] += 1

    # List of unique values
    values = list(value_count.keys())
    value_indices = {v: i for i, v in enumerate(values)}

    # dp[i][j]: number of ways to arrange the first j elements using first i types of elements
    # ending with an element of the i-th type
    dp = [[0] * (len(values) + 1) for _ in range(len(values) + 1)]
    dp[0][0] = 1

    # dp[i][j]: we have used exactly j elements, last is i-th type
    # For each possible state (i, j)
    for i in range(len(values) + 1):
        for j in range(len(values) + 1):
            if j == 0:
                continue
            # If dp[i][j] > 0, we can extend by any type k not equal to i
            for k in range(len(values) + 1):
                if k == i:
                    continue
                # Check if we can place type k next
                if i < len(values) and k < len(values):
                    value_i = values[i]
                    value_k = values[k]
                    if not is_perfect_square(value_i * value_k):
                        # Can place type k after type i
                        if j <= value_count[value_i]:
                            # We can place one more element of type k
                            if j - 1 <= value_count[value_k]:
                                dp[k][j] += dp[i][j]

    # Need to count all permutations, not just up to j
    result = 0
    for j in range(len(values) + 1):
        result += dp[len(values)][j]
    return result

n = int(input())
a = list(map(int, input().split()))
print(count_right_permutations(n, a))
