@lru_cache(maxsize=None)
def dp(mask, last_value):
    # mask: integer representing which values are used
    # last_value: the last value in the sequence
    if mask == (1 << len(values)) - 1:
        return 1

    total = 0
    for i, val in enumerate(values):
        if not (mask & (1 << i)) and val != last_value and not is_perfect_square(last_value * val):
            total += dp(mask | (1 << i), val)
    return total

