import math

def lcm(a, b):
    return a * b // math.gcd(a, b)

def string_lcm(s, t):
    len_s = len(s)
    len_t = len(t)
    L = lcm(len_s, len_t)

    # Generate candidate strings
    candidate1 = s * (L // len_s)
    candidate2 = t * (L // len_t)

    # Check if candidate1 matches pattern of t
    matches_t = True
    for i in range(len(candidate1)):
        if candidate1[i] != t[i % len_t]:
            matches_t = False
            break

    # Check if candidate2 matches pattern of s
    matches_s = True
    for i in range(len(candidate2)):
        if candidate2[i] != s[i % len_s]:
            matches_s = False
            break

    if matches_t:
        return candidate1
    elif matches_s:
        return candidate2
    else:
        return -1

q = int(input())
for _ in range(q):
    s = input().strip()
    t = input().strip()
    print(string_lcm(s, t))
