import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    stamps = []
    idx = 1
    for _ in range(n):
        a = int(data[idx])
        b = int(data[idx + 1])
        stamps.append((a, b))
        idx += 2

    # Start with the first stamp in both possible orientations
    for first_start, first_end in [(stamps[0][0], stamps[0][1]), (stamps[0][1], stamps[0][0])]:
        path = [first_start, first_end]
        current_start = first_start
        current_end = first_end

        # Try to build the path
        for i in range(1, n):
            a, b = stamps[i]

            # Try to extend from the end
            if current_end == a:
                path.append(b)
                current_end = b
            elif current_end == b:
                path.append(a)
                current_end = a

            # If we couldn't extend from the end, try to extend from the start
            elif current_start == a:
                path.insert(0, b)
                current_start = b
            elif current_start == b:
                path.insert(0, a)
                current_start = a

            # If we still can't extend, then the edge is between the current start and end
            else:
                # Check if a is between start and end
                if current_start == a:
                    path.insert(0, b)
                    current_start = b
                elif current_start == b:
                    path.insert(0, a)
                    current_start = a
                else:
                    # Check if b is between start and end
                    if current_start == a:
                        path.insert(0, b)
                        current_start = b
                    elif current_start == b:
                        path.insert(0, a)
                        current_start = a
                    else:
                        # This means we need to extend both directions
                        if current_start == a:
                            path.insert(0, b)
                            current_start = b
                        elif current_start == b:
                            path.insert(0, a)
                            current_start = a
                        else:
                            path.append(a)
                            path.append(b)
                            current_start = a
                            current_end = b

        # Check if we built a valid path
        if len(path) == n + 1:
            print(' '.join(map(str, path)))
            return

if __name__ == "__main__":
    solve()
"}

