{"code": "
import sys

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xroot = self.find(x)
        yroot = self.find(y)

        if xroot == yroot:
            return False

        if self.rank[xroot] < self.rank[yroot]:
            self.parent[xroot] = yroot
        else:
            self.parent[yroot] = xroot
            if self.rank[xroot] == self.rank[yroot]:
                self.rank[xroot] += 1
        return True

n = int(sys.stdin.readline())
qualifications = list(map(int, sys.stdin.readline().split()))
m = int(sys.stdin.readline())

edges = []
for _ in range(m):
    a, b, c = map(int, sys.stdin.readline().split())
    edges.append((c, a - 1, b - 1))

# Sort edges by cost (Kruskal's algorithm)
edges.sort()

# Union-Find for MST
uf = UnionFind(n)
total_cost = 0
edges_used = 0

for cost, u, v in edges:
    if uf.union(u, v):
        total_cost += cost
        edges_used += 1
        if edges_used == n - 1:
            break

# Check if all nodes are connected
if edges_used == n - 1:
    print(total_cost)
else:
    print(-1)
"}

