    # For each counter i, we want: x_i + sum(neighbors) = 1

    x = [0] * n

    # Try to achieve value 1 for each counter
    for i in range(n):
        val = 0
        for j in graph[i]:
            val += x[j]
        if val == 1:
            continue
        if val == 0:
            x[i] = 1
        else:
