def apply_smoothing(seq, n):
    """Apply median smoothing to a sequence of 0s and 1s"""
    new_seq = seq[:]
    new_seq[0] = seq[0]
    new_seq[n - 1] = seq[n - 1]

    for i in range(1, n - 1):
        # Median of three values
        if seq[i - 1] == seq[i] and seq[i] == seq[i + 1]:
            new_seq[i] = seq[i]
        else:
            if seq[i - 1] == seq[i]:
                new_seq[i] = seq[i]
            elif seq[i] == seq[i + 1]:
                new_seq[i] = seq[i]
            else:
                # All three different
                # In the case of 0,1,0 or 1,0,1, the median is the middle value
                # When sorted, the middle value is 0
                new_seq[i] = 0

    return new_seq


def solve():
    n = int(input())
    seq = list(map(int, input().split()))

    iterations = 0

    while True:
        next_seq = apply_smoothing(seq, n)

        if next_seq == seq:
            print(iterations)
            print(' '.join(map(str, seq)))
            return

        seq = next_seq
        iterations += 1

        # In theory, it should always stabilize for binary sequences
        # But we can add a safety check
        if iterations > 100:
            print(-1)
            return

solve()
