def find_centroids(tree, n):
    """Find all centroids of the tree"""
    def dfs(u, parent, size):
        for v in tree[u]:
            if v != parent:
                size[u] += dfs(v, u, size)
        return size[u]

    sizes = [0] * (n + 1)
    for i in range(1, n + 1):
        if sizes[i] == 0:
            dfs(i, -1, sizes)

    # Find centroids by checking component sizes when removing each vertex
    centroids = []
    for i in range(1, n + 1):
        comp_sizes = []
        for j in range(1, n + 1):
            if j == i:
                continue
            comp_sizes.append(sizes[j])

        if sizes[i] > 0:
            comp_sizes.append(sizes[i])  # component containing i

        # The largest component size
        largest = max(comp_sizes)
        centroids.append((i, largest))

    centroids.sort(key=lambda x: x[1])
    # The maximum component size after removing any vertex
    max_component_size = max(x[1] for x in centroids)

    # Only vertices with largest component size equal to max_component_size are centroids
    final_centroids = [x[0] for x in centroids if x[1] == max_component_size]
    return final_centroids

