import sys
from collections import defaultdict

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    m = int(next(it))
    k = int(next(it))
    n = int(next(it))
    s = int(next(it))
    a = [int(next(it)) for _ in range(m)]
    b = [int(next(it)) for _ in range(s)]

    # Compute frequencies of b
    freq_b = defaultdict(int)
    for t in b:
        freq_b[t] += 1

    # Sliding window
    cnt = defaultdict(int)
    found = False
    pos = -1  # start position of window
    for i in range(m):
        cnt[a[i]] += 1
        if i >= k:
            cnt[a[i-k]] -= 1
            if cnt[a[i-k]] == 0:
                del cnt[a[i-k]]
        if i >= k - 1:
            ok = True
            for t, need in freq_b.items():
                if cnt[t] < need:
                    ok = False
                    break
            if ok:
                found = True
                pos = i - k + 1  # 0-indexed start
                break

    if not found:
        print(-1)
        return

    # Construct answer: keep window + extra
    kept = []
    window_start = pos  # 0-indexed
    window_end = pos + k - 1
    for i in range(m):
        if window_start <= i <= window_end:
            kept.append(i + 1)  # 1-indexed

    extra = (n - 1) * k
    for i in range(m):
        if not (window_start <= i <= window_end):
            kept.append(i + 1)
            if len(kept) == n * k:
                break

    # Output
    removed = []
    for i in range(1, m + 1):
        if i not in kept:
            removed.append(i)

    print(len(removed))
    if removed:
