def find_centroid(tree, n):

    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for v, u in tree:
        graph[v].append(u)
        graph[u].append(v)

    def dfs(v, parent, size):
        # Return size of subtree rooted at v
        res = 1
        for u in graph[v]:
            if u != parent:
                res += dfs(u, v, size)
        return res

    def is_centroid(v, parent, size, n):
        # Check if v is a centroid
        max_comp = 0
        for u in graph[v]:
            if u != parent:
                comp = dfs(u, v, size)
                max_comp = max(max_comp, comp)
        return max_comp <= n // 2

    # Find all centroids
    centroids = []
    for v in range(1, n + 1):
        is_cen = is_centroid(v, -1, dfs(v, -1, 0), n)
        if is_cen:
            centroids.append(v)
    return centroids


def solve(t, test_cases):
