import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1] if len(data) > 1 else ""

    MOD = 998244353
    ans = 0

    for i in range(n):
        for j in range(i, n):
            # Remove substring [i, j]
            # Check if what's left is all equal
            # Left part: s[0..i-1]
            # Right part: s[j+1..n-1]
            # They must be all equal and contiguous

            # Find the set of characters in left and right
            left_set = set()
            for k in range(i):
                left_set.add(s[k])

            right_set = set()
            for k in range(j+1, n):
                right_set.add(s[k])

            if left_set == right_set:
                # Left and right have the same characters
                # Now check if they're all the same character
                # They must be all one character
                if len(left_set) == 0:
                    # Left is empty, right must be all one character
                    if len(right_set) == 1:
                        ans += 1
                elif len(right_set) == 0:
                    # Right is empty, left must be all one character
                    if len(left_set) == 1:
                        ans += 1
                else:
                    # Both are non-empty, they must be equal
                    if left_set == right_set and len(left_set) == 1:
                        ans += 1

    print(ans % MOD)

if __name__ == "__main__":
    solve()
