    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1] if len(data) > 1 else ""

    MOD = 998244353
    ans = 0

    for i in range(n):
        for j in range(i, n):
            # Remove substring [i, j]
            # Check if what's left is all equal

            # Left part: s[0..i-1]
            left = set()
            for k in range(i):
                left.add(s[k])

            # Right part: s[j+1..n-1]
            right = set()
            for k in range(j+1, n):
                right.add(s[k])

            if len(left) == 0 and len(right) == 0:
                # Both empty, count as valid
                ans += 1
            elif len(left) == 0:
                # Left empty, right must be all one character
                if len(right) == 1:
                    ans += 1
            elif len(right) == 0:
                # Right empty, left must be all one character
                if len(left) == 1:
                    ans += 1
            else:
                # Both non-empty, must be equal and one character
                if left == right and len(left) == 1:
                    ans += 1

    print(ans % MOD)

if __name__ == "__main__":
    solve()
