def check_plus_shape(h, w, grid):

    # Find center star
    center = None
    for i in range(h):
        for j in range(w):
            if grid[i][j] == '*':
                center = (i, j)
                break
        if center:
            break

    if not center:
        return False  # No center star

    # Check rays in all four directions
    # Up
    up_row = center[0] - 1
    while up_row >= 0:
        if grid[up_row][center[1]] == '*':
            up_row -= 1
        else:
            break

    # Down
    down_row = center[0] + 1
    while down_row < h:
        if grid[down_row][center[1]] == '*':
            down_row += 1
        else:
            break

    # Left
    left_col = center[1] - 1
    while left_col >= 0:
        if grid[center[0]][left_col] == '*':
            left_col -= 1
        else:
            break

    # Right
    right_col = center[1] + 1
    while right_col < w:
        if grid[center[0]][right_col] == '*':
            right_col += 1
        else:
            break

    # Check if rays are connected and extend beyond center
    if up_row >= center[0] or down_row <= center[0] or left_col >= center[1] or right_col <= center[1]:
        return False  # Rays must extend beyond center

    # Check if all other stars are within the rays
    for i in range(h):
        for j in range(w):
            if grid[i][j] == '*':
                if (i == center[0] and j != center[1] and j < left_col) or (i == center[0] and j != center[1] and j > right_col):
                    return False  # Left ray too short
                if (i != center[0] and j == center[1] and i < up_row) or (i != center[0] and j == center[1] and i > down_row):
                    return False  # Up ray too short
                if (i != center[0] and j == center[1] and i < up_row) or (i != center[0] and j == center[1] and i > down_row):
                    return False  # Down ray too short
                if (i == center[0] and j != center[1] and j < left_col) or (i == center[0] and j != center[1] and j > right_col):
                    return False  # Right ray too short

    return True

def solve():
    h, w = map(int, input().split())
    grid = []
    for i in range(h):
        grid.append(input())

    if check_plus_shape(h, w, grid):
        print("YES")
    else:
        print("NO")

