def is_valid_12(time_str):
    hour_str = time_str[:2]
    min_str = time_str[3:]

    # Hours: 1-12
    hour = int(hour_str)
    if hour < 1 or hour > 12:
        return False

    # Minutes: 0-59
    min = int(min_str)
    if min < 0 or min > 59:
        return False

    return True

def is_valid_24(time_str):
    hour_str = time_str[:2]
    min_str = time_str[3:]

    # Hours: 0-23
    hour = int(hour_str)
    if hour < 0 or hour > 23:
        return False

    # Minutes: 0-59
    min = int(min_str)
    if min < 0 or min > 59:
        return False

    return True

def solve(format_type, broken_time):
    # Check if it's already valid
    if is_valid_24(broken_time) if format_type == 24 else is_valid_12(broken_time):
        return broken_time

    best_time = broken_time
    best_changes = 4  # Maximum changes (all digits different)

    # Try all possible valid times
    for h0 in range(10):
        for h1 in range(10):
            for m0 in range(10):
                for m1 in range(10):
                    time_str = f"{h0}{h1}:{m0}{m1}"

                    # Check if valid
                    if is_valid_24(time_str) if format_type == 24 else is_valid_12(time_str):
                        changes = sum(1 for i in range(4) if time_str[i] != broken_time[i])

                        # Update best time
                        if changes < best_changes:
                            best_changes = changes
                            best_time = time_str
                        elif changes == best_changes:
                            # For ties, prefer the one that changes fewer original digits
                            # Actually, we should just take the lexicographically smallest
                            if time_str < best_time:
                                best_time = time_str

    return best_time

# Read input
