    """Check if n is a perfect square"""
    s = int(n**0.5)
    return s * s == n

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # DP: dp[mask][last_index] = number of ways
    dp = [[0] * n for _ in range(1 << n)]

    # Initialize with single-element permutations
    for i in range(n):
        dp[1 << i][i] = 1

    # Iterate over all masks
    for mask in range(1, 1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue

            # Try all possible next elements
            for i in range(n):
                if mask & (1 << i):
                    continue

                # Check if product with last element is not a perfect square
                if not is_perfect_square(a[last] * a[i]):
                    dp[mask | (1 << i)][i] = (dp[mask | (1 << i)][i] + dp[mask][last]) % MOD

    # Sum all permutations of length n
    result = 0
    for i in range(n):
        result = (result + dp[(1 << n) - 1][i]) % MOD

    print(result)

