def is_valid(s):
    """Check if a substring is a valid bracket sequence"""
    stack = []
    for char in s:
        if char in '([':
            stack.append(char)
        else:
            if not stack:
                return False
            top = stack[-1]
            if (top == '(' and char == ')') or (top == '[' and char == ']'):
                stack.pop()
    return not stack

