    k = int(data[1])
    x = int(data[2])

    a = []
    idx = 3
    for _ in range(n):
        a.append(int(data[idx]))
        idx += 1

    or_val = 0

    for i in range(60, -1, -1):
        bit = 1 << i

        # Check if we can set this bit
        # We can try multiplying different numbers and see if we can get this bit

        for j in range(n):
            # Try applying operations to a[j] to see if we can get this bit
            val = a[j]
            for c in range(k + 1):
                if val & bit:
                    # We can set this bit with c operations
                    or_val |= bit

                    # Apply these operations to a[j]
                    for _ in range(c):
                        a[j] *= x

                    break

            if or_val & bit:
                break

    print(or_val)

