import math

def can_place_plates(n, R, r):
    if n == 1:
        return R >= r  # One plate just needs to touch the edge

    # The circle where plates' centers lie
    center_circle_radius = R - r

    # Angle between adjacent plates
    angle = math.pi / n  # π/n radians

    # Chord length between adjacent plates
    chord_length = 2 * center_circle_radius * math.sin(angle)

    # For plates to touch, chord length must be at least 2r
    return chord_length > 2 * r  # Changed to > instead of >=

n, R, r = map(int, input().split())

if can_place_plates(n, R, r):
    print("YES")
else:
    print("NO")
"}

