def solve() -> None:
    n, k = map(int, input().split())

    # Check if k is too large
    max_possible = n * n
    if k > max_possible:
        print(-1)
        return

    # Count how many ones we can put on the diagonal
    diag_ones = 0
    if k > 0:
        diag_ones = min(k, n)
        k -= diag_ones

    # Fill the upper triangle in row-major order
    matrix = [[0] * n for _ in range(n)]

    # Fill diagonal
    for i in range(n):
        if diag_ones > 0:
            matrix[i][i] = 1
            diag_ones -= 1
        else:
            matrix[i][i] = 0

    # Fill upper triangle
    for i in range(n):
        for j in range(i + 1, n):
            if k > 0:
                matrix[i][j] = 1
                matrix[j][i] = 1
                k -= 2
            else:
                matrix[i][j] = 0
                matrix[j][i] = 0

    # Print matrix
    for row in matrix:
        print(' '.join(map(str, row)))

solve()
"}

