t = int(input())
for _ in range(t):
    n = int(input())
    a = list(map(int, input().split()))

    # dp[i] = maximum score starting from position i (1-indexed)
    dp = [0] * (n + 2)  # Extra space to avoid index issues

    for i in range(n, 0, -1):
        jump = a[i-1]  # a[0] is position 1
        if i + jump <= n:
            dp[i] = a[i-1] + dp[i + jump]
        else:
            dp[i] = a[i-1]

    print(max(dp[1:n+1]))
